"""TypeScript backend: generate dependency-cruiser rules and extract the module graph."""

from __future__ import annotations

import json
import subprocess
import tempfile
from dataclasses import dataclass
from pathlib import Path

from .model import SliceMap, exact_regex, glob_regex, prefix_regex

HEADER = (
    '// GENERATED by sliced-bread-guard from slices.toml. Do not edit by hand.\n'
    '// Regenerate: python3 tools/sliced-bread-guard/sbguard.py generate\n'
    '// The guard check fails with DRIFT when this file differs from the generated text.\n'
)


class CheckerError(Exception):
    """dependency-cruiser is missing, failed, or did not analyze every file."""


@dataclass(frozen=True)
class Edge:
    source: str
    target: str
    type_only: bool


@dataclass
class Graph:
    modules: set[str]
    edges: list[Edge]
    violations: set[tuple[str, str, str]]  # (rule, from, to) from native rules


def _rule(name: str, comment: str, source: dict, target: dict) -> dict:
    return {
        'name': name,
        'comment': comment,
        'severity': 'error',
        'from': source,
        'to': target,
    }


def config(model: SliceMap) -> dict:
    tests = glob_regex(model.test_patterns)
    rules = [
        _rule(
            'SB-00/unresolvable',
            'Analysis integrity: an import the checker cannot resolve hides an edge.',
            {},
            {'couldNotResolve': True},
        ),
        _rule(
            'SB-05/no-production-to-test',
            'Production code does not import test files.',
            {'pathNot': tests},
            {'path': tests},
        ),
    ]
    for node in model.slices:
        inside, crust = prefix_regex(node.paths), exact_regex(node.crust)
        rules.append(
            _rule(
                f'SB-01/crust-only/{node.name}',
                f'Production code outside {node.name} imports only its crust.',
                {'pathNot': f'(?:{inside})|(?:{tests})'},
                {'path': inside, 'pathNot': crust},
            )
        )
        rules.append(
            _rule(
                f'SB-05/test-crust-only/{node.name}',
                f'Tests outside {node.name} import only its crust.',
                {'path': tests, 'pathNot': inside},
                {'path': inside, 'pathNot': crust},
            )
        )
    for node in model.nodes:
        allowed = set(node.may_depend_on) | {node.name}
        denied = [n for n in model.nodes if n.name not in allowed]
        if not denied:
            continue
        rules.append(
            _rule(
                f'SB-02/allowed-edges/{node.name}',
                f'{node.name} may depend only on: {", ".join(node.may_depend_on) or "nothing"}.',
                {'path': prefix_regex(node.paths)},
                {'path': prefix_regex(tuple(p for n in denied for p in n.paths))},
            )
        )
    options: dict = {
        'tsPreCompilationDeps': True,
        'doNotFollow': {'path': '(^|/)node_modules/'},
        'exclude': {'path': '(^|/)node_modules/'},
    }
    if model.tsconfig:
        options['tsConfig'] = {'fileName': model.tsconfig}
    return {'forbidden': rules, 'options': options}


def render(model: SliceMap) -> str:
    return HEADER + 'module.exports = ' + json.dumps(config(model), indent=2) + '\n'


def extract(root: Path, model: SliceMap, files: list[str]) -> Graph:
    binary = root / 'node_modules' / '.bin' / 'depcruise'
    if not binary.exists():
        raise CheckerError(f'dependency-cruiser not installed: {binary} is missing (run npm ci)')
    with tempfile.TemporaryDirectory(prefix='sbguard-') as scratch:
        config_path = Path(scratch) / 'config.cjs'
        config_path.write_text(render(model), encoding='utf8')
        output = Path(scratch) / 'out.json'
        run = subprocess.run(
            [str(binary), '--config', str(config_path), '--output-type', 'json', '-f', str(output), '--', *files],
            cwd=root,
            capture_output=True,
            text=True,
        )
        try:
            data = json.loads(output.read_text(encoding='utf8'))
            summary = data['summary']
            modules = data['modules']
        except (OSError, ValueError, KeyError):
            raise CheckerError(
                f'dependency-cruiser failed (exit {run.returncode}): {run.stderr.strip()[:2000]}'
            ) from None

    edges: list[Edge] = []
    for module in modules:
        for dep in module.get('dependencies', []):
            if dep.get('couldNotResolve') or dep.get('coreModule'):
                continue
            types = dep.get('dependencyTypes', [])
            edges.append(Edge(module['source'], dep['resolved'], 'type-only' in types))
    violations = set()
    for item in summary.get('violations', []):
        rule = item['rule']['name'].split('/', 1)[0]
        if item.get('type') != 'dependency':
            raise CheckerError(f'unexpected dependency-cruiser violation type: {item.get("type")}')
        violations.add((rule, item['from'], item['to']))
    analyzed = {m['source'] for m in modules}
    missing = sorted(set(files) - analyzed)
    if missing:
        raise CheckerError('dependency-cruiser did not analyze: ' + ', '.join(missing[:20]))
    return Graph(modules=analyzed, edges=edges, violations=violations)
